import java.util.Map;

public class MessagePrinter {
    private Map<String, Integer> messageTimestamps;

    public MessagePrinter() {
        messageTimestamps = new HashMap<>();
    }

    public boolean shouldPrintMessage(int timestamp, String message) {
        if (messageTimestamps.containsKey(message)) {
            int lastPrintedTime = messageTimestamps.get(message);
            if (timestamp - lastPrintedTime < 10) {
                return false;
            }
        }
        messageTimestamps.put(message, timestamp);
        return true;
    }

    public static void main(String[] args) {
        MessagePrinter printer = new MessagePrinter();
        System.out.println(printer.shouldPrintMessage(10, "Hello")); // true
        System.out.println(printer.shouldPrintMessage(11, "Hello")); // false
        System.out.println(printer.shouldPrintMessage(15, "Hello")); // true
    }
}

