import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.channels.FileChannel;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.logging.Logger;

public class ClassReader {
    private ByteBuffer buffer;
    private Logger LOG = Logger.getLogger(ClassReader.class.getName());

    public ClassReader(final ByteBuffer buffer) {
        this.buffer = buffer;
    }

    public long readLong(final int offset) {
        if (offset < 0 || offset + 8 > buffer.remaining()) {
            throw new IndexOutOfBoundsException("Offset out of bounds");
        }
        buffer.position(offset);
        return buffer.getLong();
    }

    public static void main(String[] args) {
        try {
            Path path = Paths.get("example.class");
            byte[] bytes = Files.readAllBytes(path);
            ByteBuffer buffer = ByteBuffer.wrap(bytes);
            ClassReader reader = new ClassReader(buffer);
            long value = reader.readLong(0);
            System.out.println("Read long value: " + value);
