            throw new IllegalArgumentException("Invalid constant pool entry index");
        }

        int utf8Length = classFileBuffer.getShort(constantPoolEntryIndex + 1);
        if (utf8Length < 0) {
            throw new IllegalArgumentException("Invalid UTF-8 length");
        }

        if (utf8Length > charBuffer.length) {
            throw new IllegalArgumentException("Character buffer is too small");
        }

        classFileBuffer.position(constantPoolEntryIndex + 3);
        classFileBuffer.get(charBuffer, 0, utf8Length);

        return new String(charBuffer, 0, utf8Length);
    }
}

