     * Split a box along the x axis into two equal boxes.
     * @param box the box to split
     * @return a pair with the two resulting boxes
     */
    public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
        double midX = box.getX() + (box.getWidth() / 2.0);
        Box2D box1 = new Box2D(box.getX(), box.getY(), midX - box.getX(), box.getHeight());
        Box2D box2 = new Box2D(midX, box.getY(), box.getX() + (box.getWidth() / 2.0) - midX, box.getHeight());
        return Pair.with(box1, box2);
    }
}

