import java.util.Set;

public class GraphUtils {

    /** 
     * Check whether the subgraph of <code>graph</code> induced by the given <code>vertices</code> is complete, i.e. a clique.
     * @param graph the graph.
     * @param vertices the vertices to induce the subgraph from.
     * @return true if the induced subgraph is a clique.
     */
    private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
        if (vertices == null || vertices.isEmpty()) {
            return true; // An empty set or null set is trivially a clique
        }

        for (V vertex : vertices) {
            for (V otherVertex : vertices) {
                if (vertex.equals(otherVertex)) {
                    continue; // Skip self-loops
                }
                if (!graph.containsEdge(vertex, otherVertex)) {
                    return false; // If there is an edge between any two vertices, it's not a clique
                }
            }
        }
        return true; // All vertices are connected to each other, so it's a clique
    }

    public static void main(String[] args) {
        // Example usage
        // Assuming a simple graph implementation
        Graph<Integer, Integer> graph = new SimpleGraph<>();
        graph.addEdge(1, 2);
        graph.addEdge(1, 3);
        graph.addEdge(2, 3);

        Set<Integer> vertices = Set.of(1, 2, 3);
        System.out.println(isClique(graph, vertices)); // Output: true
    }
}

